// Map whatever trigger fired into { path: <Windows path for the runner>, original: <basename>, trigger: <which> }
const cfg = $('Config').first().json;
const j = $input.first().json;

let raw = null;
let trigger = 'manual';
if (j.path && typeof j.path === 'string' && !j.body) {
  raw = j.path; trigger = 'file';                 // Local File Trigger → { event, path }
} else if (j.body && j.body.path) {
  raw = j.body.path; trigger = 'webhook';         // Webhook → { body: { path } }
} else {
  raw = cfg.MANUAL_PATH; trigger = 'manual';      // Manual Trigger → Config.MANUAL_PATH
}
if (!raw) throw new Error('No input path. Set Config.MANUAL_PATH or POST {"path": ...} to the webhook.');

// Container path → Windows path (only when the path starts with CONTAINER_INBOX).
let winPath = raw;
const cInbox = (cfg.CONTAINER_INBOX || '').replace(/\/+$/, '');
if (cInbox && raw.startsWith(cInbox + '/')) {
  const rel = raw.slice(cInbox.length + 1).replace(/\//g, '\\');
  winPath = cfg.INBOX.replace(/\\+$/, '') + '\\' + rel;
}
const original = winPath.split(/[\\/]/).pop();
return [{ json: { path: winPath, raw_path: raw, original, trigger } }];

// Ollama Verdict failed (runner down mid-run, Ollama off, timeout...). Keep going without the LLM.
const predict = $('Predict').first().json;
const err = $input.first().json;
const reason = (err && (err.error && (err.error.message || err.error))) || err.message || 'request failed';
const candidates = (predict.candidates || []).map(c => ({ ...c, llm: null, llm_error: String(reason) }));
return [{ json: { ok: true, candidates, recommended: predict.recommended, llm_error: String(reason) } }];

// Produce the review text exactly as CONTRACT.md specifies.
const cfg = $('Config').first().json;
const ingest = $('Ingest').first().json;
const norm = $('Normalize Input').first().json;
const transcribe = $('Transcribe').first().json;
const inp = $input.first().json;
const candidates = inp.candidates || [];
const recommended = inp.recommended ?? $('Predict').first().json.recommended ?? null;

function hms(sec) {
  sec = Math.max(0, Math.round(Number(sec) || 0));
  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
  return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}
function r0(x) { return Math.round(Number(x) || 0); }

const lines = [];
lines.push(`🎬 Personal Clipper — ${norm.original || ingest.source} (${hms(ingest.duration_sec)})`);
if (transcribe && transcribe.words === 0) lines.push(`(transcription: ${transcribe.note || 'no speech detected'} — scores rely on audio only)`);
for (const c of candidates) {
  const p = c.predict || {};
  const star = (recommended !== null && c.rank === recommended) ? ' ⭐ recommended' : '';
  lines.push(`#${c.rank}  score ${r0(p.total)}/100  (hook ${r0(p.hook)} · retention ${r0(p.retention)} · clarity ${r0(p.clarity)} · length ${r0(p.length_fit)})   ${hms(c.start)} → ${hms(c.end)}${star}`);
  lines.push(`    why: ${c.reason || '-'}`);
  lines.push(`    fix: ${p.biggest_fix || '-'}`);
  if (c.llm === null || c.llm === undefined) {
    lines.push(`    llm: (LLM unavailable: ${c.llm_error || inp.llm_error || 'unknown'})`);
  } else {
    const flag = c.llm.agrees === false ? '⚠️ disagrees' : '✅ agrees';
    const fixTxt = c.llm.fix ? ` — fix: ${c.llm.fix}` : '';
    lines.push(`    llm: "${c.llm.verdict || ''}"${fixTxt} ${flag}`);
  }
}
const hours = cfg.REVIEW_TIMEOUT_HOURS || 24;
lines.push(`Reply: a number (e.g. 2), "2 start 5s earlier", "2 end 3s later", or "reject all". No reply in ${hours} h = nothing rendered.`);
lines.push(`Reply in this chat with a number (e.g. 2), '2 start 5s earlier', or 'reject all'. No reply within ${hours} h = nothing rendered.`);

return [{ json: {
  text: lines.join('\n'),
  job_id: ingest.job_id,
  job_dir: ingest.job_dir,
  input: norm.path,
  original: norm.original,
  duration_sec: ingest.duration_sec,
  candidates,
  recommended,
} }];

// Start the getUpdates poll loop. Carries the review payload along; `text` of the review becomes `review_text`
// so that `text` is free for the user's reply (Find Reply writes it there).
const cfg = $('Config').first().json;
const review = $('Build Review Message').first().json;
const sent = $input.first().json;              // Telegram sendMessage result (message object)
const sent_at = Math.floor(Date.now() / 1000);
const hours = Number(cfg.REVIEW_TIMEOUT_HOURS) || 24;
const { text, ...rest } = review;
return [{ json: {
  ...rest,
  review_text: text,
  review_message_id: sent && sent.message_id ? sent.message_id : null,
  sent_at,
  deadline: sent_at + hours * 3600,
  poll_offset: 0,
  attempts: 0,
} }];

// Look for the user's reply among the getUpdates results. Loop state comes from the last run of `Wait 20s`
// (so it is still intact if getUpdates failed and `continue on fail` produced an {error} item).
const cfg = $('Config').first().json;
const state = $('Wait 20s').first().json;
const resp = $input.first().json || {};
const chatId = String(cfg.TELEGRAM_CHAT_ID);
const now = Math.floor(Date.now() / 1000);

const updates = (resp.ok === true && Array.isArray(resp.result)) ? resp.result : [];
let maxId = null;
let best = null;
for (const u of updates) {
  if (typeof u.update_id === 'number') maxId = maxId === null ? u.update_id : Math.max(maxId, u.update_id);
  const m = u.message;
  if (!m || !m.chat || String(m.chat.id) !== chatId) continue;
  if (!(Number(m.date) > Number(state.sent_at))) continue;
  if (typeof m.text !== 'string' || !m.text.trim()) continue;
  if (!best || Number(m.date) >= Number(best.date)) best = m;   // newest wins
}
const next_offset = maxId === null ? Number(state.poll_offset) || 0 : maxId + 1;
const attempts = (Number(state.attempts) || 0) + 1;
const poll_error = resp.error ? String(resp.error.message || resp.error) : (resp.ok === false ? String(resp.description || 'getUpdates not ok') : null);

const { found: _f, text: _t, ...carry } = state;
if (best) {
  return [{ json: { ...carry, found: true, text: best.text.trim(), reply_date: best.date, next_offset, attempts, timed_out: false, poll_error: null } }];
}
return [{ json: { ...carry, found: false, next_offset, attempts, timed_out: now >= Number(state.deadline), poll_error } }];

// Implements the CONTRACT.md reply grammar.
const review = $('Build Review Message').first().json;
const cfg = $('Config').first().json;
const raw = String($input.first().json.text || '').trim();   // set by Find Reply
const text = raw.toLowerCase().replace(/\s+/g, ' ');
const duration = Number(review.duration_sec) || 0;

const GRAMMAR = /^(\d)(?:\s*(?:start|end)\s*([+-]?\d+(?:\.\d+)?)\s*s?\s*(earlier|later)?)*$|^reject all$/i;

const base = { reply: raw, job_id: review.job_id, job_dir: review.job_dir, input: review.input,
               original: review.original, candidates: review.candidates };

if (text === 'reject all') return [{ json: { ...base, action: 'reject' } }];
if (!GRAMMAR.test(text)) return [{ json: { ...base, action: 'invalid', error: `Could not parse reply "${raw}"` } }];

const rank = Number(text.match(/^(\d)/)[1]);
const cand = (review.candidates || []).find(c => Number(c.rank) === rank);
if (!cand) return [{ json: { ...base, action: 'invalid', error: `No candidate #${rank}` } }];

let start = Number(cand.start), end = Number(cand.end);
const clauseRe = /(start|end)\s*([+-]?\d+(?:\.\d+)?)\s*s?\s*(earlier|later)?/g;
let m;
while ((m = clauseRe.exec(text)) !== null) {
  const which = m[1];
  let delta = parseFloat(m[2]);
  const dir = m[3];
  if (dir === 'earlier') delta = -Math.abs(delta);
  else if (dir === 'later') delta = Math.abs(delta);
  // no direction word: signed number is taken literally (+ = later, - = earlier)
  if (which === 'start') start += delta; else end += delta;
}
const clamp = v => Math.min(Math.max(0, v), duration || v);
start = clamp(start); end = clamp(end);
if (end <= start) return [{ json: { ...base, action: 'invalid', error: `Window collapsed (start ${start}s ≥ end ${end}s)` } }];

return [{ json: { ...base, action: 'render', rank, start: Number(start.toFixed(3)), end: Number(end.toFixed(3)),
                  duration: Number((end - start).toFixed(3)), candidate: { ...cand, start, end },
                  captions: cfg.CAPTIONS !== false, offset: cfg.RENDER_OFFSET, audio_mode: cfg.AUDIO_MODE, volume: cfg.VOLUME } }];
